#!/usr/bin/env python3
"""The check for banned-api/seed. Generated by eval/build_tasks.py; run it
as `python3 check.py <workspace>`. Exit 0 is a pass."""

import json
import re
import shutil
import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parents[3]))
from checklib import CAMEL, SNAKE, main  # noqa: E402


def check(ws):
    ws.check("./dev test passes", *ws.dev("test"))
    ws.check("the task's own assertions", *ws.py('import datetime as d\nfrom tally import clock, invoice\nfrom tests.support import sample_invoice\nclock.freeze(d.date(2024, 4, 10)); assert invoice.days_overdue(sample_invoice()) == 10\nclock.freeze(d.date(2024, 3, 20)); assert invoice.days_overdue(sample_invoice()) == 0', env=None))
    ws.signals["followed"] = "clock." in ws.read('tally/invoice.py')


if __name__ == "__main__":
    main(check)
